Both composites are a few lines because the interface is tiny: one method returning a spot or `None`. Returning `None` instead of raising is what makes the fallback trivial. The property test recomputes the set of usable spots independently and checks every strategy against it, which finds mistakes such as ignoring floors under maintenance or returning a spot of the wrong type. The lesson's design code is assumed to live in `parking/design.py`.

**`parking/composite_strategies.py`**

```python
from collections.abc import Mapping

from parking.design import ParkingLot, ParkingSpot, SpotAssignmentStrategy, VehicleType


class FallbackSpotStrategy(SpotAssignmentStrategy):
    """Try each strategy in order; the first one that finds a spot wins."""

    def __init__(self, *strategies: SpotAssignmentStrategy) -> None:
        if not strategies:
            raise ValueError("at least one strategy is required")
        self._strategies = strategies

    def assign(self, lot: ParkingLot, vehicle_type: VehicleType) -> ParkingSpot | None:
        for strategy in self._strategies:
            spot = strategy.assign(lot, vehicle_type)
            if spot is not None:
                return spot
        return None


class RoutedSpotStrategy(SpotAssignmentStrategy):
    """Choose the strategy by vehicle type, with a default for unlisted types."""

    def __init__(self, routes: Mapping[VehicleType, SpotAssignmentStrategy],
                 default: SpotAssignmentStrategy) -> None:
        self._routes = dict(routes)
        self._default = default

    def assign(self, lot: ParkingLot, vehicle_type: VehicleType) -> ParkingSpot | None:
        return self._routes.get(vehicle_type, self._default).assign(lot, vehicle_type)
```

**`tests/test_composite_strategies.py`**

```python
import random

import pytest

from parking.composite_strategies import FallbackSpotStrategy, RoutedSpotStrategy
from parking.design import (
    FloorStatus, LeastAvailableFloorStrategy, NearestSpotStrategy, ParkingFloor, ParkingLot,
    ParkingSpot, SpotStatus, VehicleType,
)


def random_lot(rng: random.Random) -> ParkingLot:
    floors = []
    for number in range(rng.randint(1, 4)):
        spots = [ParkingSpot(i, rng.choice(list(VehicleType)), rng.choice(list(SpotStatus)))
                 for i in range(1, rng.randint(1, 8))]
        status = rng.choice([FloorStatus.OPERATIONAL, FloorStatus.OPERATIONAL, FloorStatus.UNDER_MAINTENANCE])
        floors.append(ParkingFloor(number, spots, status))
    return ParkingLot("random", floors, [])


def statuses(lot: ParkingLot) -> list[SpotStatus]:
    return [s.status for f in lot.floors for s in f.spots]


STRATEGIES = {
    "nearest": NearestSpotStrategy(),
    "least": LeastAvailableFloorStrategy(),
    "fallback": FallbackSpotStrategy(LeastAvailableFloorStrategy(), NearestSpotStrategy()),
    "routed": RoutedSpotStrategy({VehicleType.TRUCK: NearestSpotStrategy()}, LeastAvailableFloorStrategy()),
}


@pytest.mark.parametrize("name", sorted(STRATEGIES))
def test_every_strategy_satisfies_the_assignment_invariants(name: str) -> None:
    strategy, rng = STRATEGIES[name], random.Random(5)
    for _ in range(300):
        lot = random_lot(rng)
        for vehicle_type in VehicleType:
            before = statuses(lot)
            spot = strategy.assign(lot, vehicle_type)
            assert statuses(lot) == before                       # assignment is read-only
            usable = [s for f in lot.floors if f.status is FloorStatus.OPERATIONAL for s in f.spots
                      if s.status is SpotStatus.AVAILABLE and s.supported_vehicle_type is vehicle_type]
            if not usable:
                assert spot is None
            else:
                assert any(spot is s for s in usable)            # identity, not equality


def test_fallback_uses_the_second_strategy_only_when_the_first_finds_nothing() -> None:
    class Never(NearestSpotStrategy):
        def assign(self, lot, vehicle_type):
            return None

    lot = ParkingLot("t", [ParkingFloor(0, [ParkingSpot(1, VehicleType.CAR)])], [])
    assert FallbackSpotStrategy(Never(), NearestSpotStrategy()).assign(lot, VehicleType.CAR) is lot.floors[0].spots[0]
    with pytest.raises(ValueError):
        FallbackSpotStrategy()
```

